<section class="panel print-results"><h2><?=h($pageantStage['title'])?></h2><table class="data"><thead><tr><th>Rank</th><th>Nation</th><th>Gender</th><th>Candidate</th><th>Judge sheets</th><th>Score before deductions</th><th>Final score</th></tr></thead><tbody><?php foreach($stageRows as $rank=>$candidate):?><tr><td><?=($candidate['average']!==null?$rank+1:'—')?></td><td><?=h($candidate['team'])?></td><td><?=h($candidate['division'])?></td><td><?=h($candidate['contestant'])?></td><td><?=$candidate['entries']?></td><td><?=$candidate['raw_average']===null?'—':number_format($candidate['raw_average'],2).'% / 100%'?></td><td><?=$candidate['average']===null?'—':number_format($candidate['average'],2).'% / 100%'?></td></tr><?php endforeach;?><?php if(!$stageRows):?><tr><td colspan="7" class="empty">No scores recorded for this stage.</td></tr><?php endif;?></tbody></table></section>
<?php endforeach;endif;?>
<?php if($isPageant&&$page==='results'):?><section class="panel no-print"><h2>Recorded candidate score sheets</h2><table class="data"><thead><tr><th>Stage</th><th>Nation</th><th>Gender</th><th>Candidate</th><th>Judge</th><th>Score before deductions</th><th>Final score</th><th>Actions</th></tr></thead><tbody><?php foreach($scoreRows as $r):$scoreDetails=json_decode($r['details'],true)?:[];$entryStage=(string)($scoreDetails['_stage']??'preliminary');?><tr><td><?=h($entryStage==='final'?'Final Interview':'Preliminary exposures')?></td><td><?=h($r['team'])?></td><td><?=h($r['division'])?></td><td><?=h($r['contestant'])?></td><td><?=h($r['judge'])?></td><td><?=$r['raw']===null?'—':number_format((float)$r['raw'],2).'% / 100%'?></td><td><?=$r['final']===null?'—':number_format((float)$r['final'],2).'% / 100%'?></td><td><a href="?page=score&amp;event=<?=$eid?>&amp;edit=<?=$r['id']?>">Edit</a> · <a target="_blank" href="print-score.php?id=<?=$r['id']?>">Print</a> <?php if(admin()):?>· <form method="post" class="inline" onsubmit="return confirm('Delete this candidate score sheet?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="score_id" value="<?=$r['id']?>"><button class="link">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?>
<?php if($resultGoldRows):?><section class="panel no-print"><h2><?=h($e['name'])?> · Gold Award Review</h2><table class="data"><thead><tr><th>Event</th><th>Division</th><th>Award</th><th>Nation</th><th>Winner / recipient</th><th>Gold</th><th>Notes</th></tr></thead><tbody><?php foreach($resultGoldRows as $award):?><tr><td><?=h($e['name'])?></td><td><?=h($award['division'])?></td><td><?=h($award['award_name'])?></td><td><?=h($award['team'])?></td><td><?=h($award['winner_name'])?></td><td><?=number_format((float)$award['gold_points'],2)?></td><td><?=h($award['notes'])?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="5">Selected event total</th><th><?=number_format((float)$resultGoldTotal,2)?></th><th></th></tr></tfoot></table><div class="actions"><a class="button" target="_blank" href="print-gold-result.php?event=<?=$eid?><?=$divisionFilter!==''?'&amp;division='.rawurlencode($divisionFilter):''?>">Print event result</a></div></section><?php endif;?>
<?php if($scoreRows&&!$isPageant):?>
<section class="panel print-results"><h2>Entered overall scores</h2><p class="muted">Score-sheet totals before authorized deductions.</p><table class="data"><thead><tr><th>Nation</th><th>Division</th><th>Overall input<?=$rubricMax!==null?' (%)':''?></th></tr></thead><tbody><?php foreach($standing as $t):?><tr><td><?=h($t['team'])?></td><td><?=h($t['division'])?></td><td><?php if($t['raw_average']===null):?>—<?php elseif($rubricMax!==null):?><?=number_format($t['raw_average']/$rubricMax*100,2)?>%<?php else:?><?=number_format($t['raw_average'],2)?><?php endif;?></td></tr><?php endforeach;?><?php if(!$standing):?><tr><td colspan="3" class="empty">No scores recorded yet.</td></tr><?php endif;?></tbody></table></section>
<?php if($page==='results'):?><section class="panel no-print"><h2>Recorded score sheets</h2><table class="data"><thead><tr><th>Rank</th><th>Nation</th><th>Contestant</th><th>Judge</th><th>Final<?=$rubricMax!==null?' (%)':''?></th><th>Result</th><th>Actions</th></tr></thead><tbody><?php foreach($scoreRows as $r):$teamRank=provisional_rank_for_score($r,$scoreRows);?><tr><td><?=($teamRank!==null?$teamRank . ordinal_suffix($teamRank):'—')?></td><td><?=h($r['team'])?></td><td><?=h($r['contestant'])?></td><td><?=h($r['judge'])?></td><td><?php if($r['final']===null):?>—<?php elseif($rubricMax!==null):?><?=number_format((float)$r['final']/$rubricMax*100,2)?>%<?php else:?><?=h($r['final'])?><?php endif;?></td><td><?=h($r['match_result'])?></td><td><a href="?page=score&event=<?=$eid?>&edit=<?=$r['id']?>">Edit</a> · <a target="_blank" href="print-score.php?id=<?=$r['id']?>">Print</a> <?php if(admin()):?>· <form method="post" class="inline" onsubmit="return confirm('Delete this entry?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="score_id" value="<?=$r['id']?>"><button class="link">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?>
<?php endif;?>

<?php endif;?><?php endif;?>
